import{_ as e,o as i,c as n,a2 as s}from"./chunks/framework.CRkTBNIT.js";const y=JSON.parse('{"title":"14.10 API Design & Recipient Rate Limiting","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.10-api-design-and-rate-limiting.md","filePath":"system-design/14.10-api-design-and-rate-limiting.md"}'),a={name:"system-design/14.10-api-design-and-rate-limiting.md"};function l(o,t,r,d,g,c){return i(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="_14-10-api-design-recipient-rate-limiting" tabindex="-1">14.10 API Design &amp; Recipient Rate Limiting <a class="header-anchor" href="#_14-10-api-design-recipient-rate-limiting" aria-label="Permalink to &quot;14.10 API Design &amp; Recipient Rate Limiting&quot;">​</a></h1><h2 id="_1-token-bucket-vs-leaky-bucket-vs-sliding-window" tabindex="-1">1. Token Bucket vs Leaky Bucket vs Sliding Window <a class="header-anchor" href="#_1-token-bucket-vs-leaky-bucket-vs-sliding-window" aria-label="Permalink to &quot;1. Token Bucket vs Leaky Bucket vs Sliding Window&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Algorithm</th><th style="text-align:left;">Smooth Bursts?</th><th style="text-align:left;">Memory Footprint</th><th style="text-align:left;">Enforcement Location</th><th style="text-align:left;">Fit for OmniPost</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Token Bucket (Chosen)</strong></td><td style="text-align:left;"><strong>Yes (allows burst up to capacity)</strong></td><td style="text-align:left;"><strong>$O(1)$ per key (tokens, timestamp)</strong></td><td style="text-align:left;"><code>queues/dispatcher.py:24</code></td><td style="text-align:left;"><strong>Optimal for provider API quotas</strong></td></tr><tr><td style="text-align:left;"><strong>Leaky Bucket</strong></td><td style="text-align:left;">No (enforces strict constant rate)</td><td style="text-align:left;">$O(1)$</td><td style="text-align:left;">Traffic shaping queues</td><td style="text-align:left;">Better for egress smoothing</td></tr><tr><td style="text-align:left;"><strong>Sliding Window Log</strong></td><td style="text-align:left;">Yes</td><td style="text-align:left;">$O(N)$ (stores every timestamp)</td><td style="text-align:left;">Redis Sorted Sets</td><td style="text-align:left;">Memory intensive</td></tr><tr><td style="text-align:left;"><strong>Fixed Window Counter</strong></td><td style="text-align:left;">Vulnerable to boundary spikes</td><td style="text-align:left;">$O(1)$</td><td style="text-align:left;">Counter cache</td><td style="text-align:left;">Poor burst protection</td></tr></tbody></table><h2 id="_2-say-it-out-loud" tabindex="-1">2. Say It Out Loud <a class="header-anchor" href="#_2-say-it-out-loud" aria-label="Permalink to &quot;2. Say It Out Loud&quot;">​</a></h2><blockquote><p>&quot;We implement token bucket rate limiting in <code>queues/dispatcher.py</code> to protect upstream carrier quotas. The token bucket smoothly accommodates legitimate bursts of OTP requests while strictly bounding average delivery throughput to provider limits (such as Twilio&#39;s 100 SMS per second). Unlike fixed-window limiters, the token bucket eliminates traffic spikes at window boundaries.&quot;</p></blockquote>',5)])])}const m=e(a,[["render",l]]);export{y as __pageData,m as default};
